parameters.body:
={
  "call_name": "Lead Call - {{ $json.fields['Full Name'] }}",
  "agent_id": "<insert agent id>",
  "agent_phone_number_id": "<insert agent phone number here>",
  "scheduled_time_unix": {{ Math.floor(Date.now() / 1000) }},
  "recipients": [
    {
      "phone_number": "{{ String($json.fields['Phone Number']).split('').filter(c => c >= '0' && c <= '9').join('') }}",
      "id": "{{ String($json.fields.ID).split('').filter(c => c >= '0' && c <= '9').join('') }}",
      "conversation_initiation_client_data":
      {
          "dynamic_variables": 
               {
                  "first_name": "{{ $json.fields["Full Name"].split(" ")[0] }}",
                  "full_name": "{{ $json.fields['Full Name'] }}",
                  "email": "{{ $json.fields.Email }}"
               }
      }
    }
  ]
}
